                    fields.Append("            private readonly __Rows rows = new __Rows();\n");
                }

                fields.Append($"            private readonly __Table{slot} {name};\n");
                constructor.Append($"                {name} = new __Table{slot}(rows);\n");
            }

            return name;
        }

